/*
 * krk_satdb.h - the compiled-in TLE table (krk_sat_tles.c, generated by tools/sat_tle_gen.py from data/tles.txt).
 */
#ifndef KRK_SATDB_H
#define KRK_SATDB_H

#define KRK_SAT_MAXN 10             /* sat_tle_gen.py MAX; sizes the screen's per-satellite pass cache */

struct krk_sat_tle {
    char name[12];
    unsigned dl_hz;                 /* satellite downlink = the radio's RX */
    unsigned ul_hz;                 /* satellite uplink = the radio's TX; 0 = none */
    unsigned short pl_x10;          /* uplink CTCSS in 0.1 Hz, 0 = none/unknown (informational: the channel's tone is stock) */
    char l1[70], l2[70];
};

extern const struct krk_sat_tle krk_sat_tles[];
extern const unsigned krk_sat_ntles;

#endif
